    if(actionType.value==='pipeline') { values.custom_pipeline_date_and_time=followup.value.next_followup; values.custom_cc_stage='PIPELINE'; }
    const update=await ccCall('cc_update_lead',{lead:detail.value.name,values:JSON.stringify(values),expected_modified:detail.value.modified,attempt:JSON.stringify({result:payload.result,reason:payload.reason,expected_modified:detail.value.modified})});
