  <header class="hdr portal-module-toolbar"><button class="hdr-btn hdr-burger" aria-label="Toggle menu" @click="$event.currentTarget.closest('.cc-erp-root').querySelector('.sidebar').classList.toggle('collapsed')">☰</button><div class="hdr-brand"><div class="logo">L</div><div><div class="bn">🎧 LIFE CALL CENTRE AGENT DASHBOARD &gt;&gt;</div><div class="bs">CC Command ERP</div></div></div><div class="hdr-center"><div class="search-wrap"><span class="si">🔍</span><input id="global-search" v-model="globalSearch" type="search" placeholder="Search client name, mobile or lead ID…" aria-label="Search all permitted leads" autocomplete="off" @keydown.esc="globalSearch=''" @keydown.enter.prevent="globalMatches.length===1&&chooseGlobal(globalMatches[0])"><div v-if="globalSearch.trim().length>=2" class="search-results show" role="region" aria-label="Lead search results"><div v-if="globalSearchBusy" class="sr-item" role="status">Searching all permitted history…</div><div v-else-if="globalSearchError" class="sr-item" role="alert">{{globalSearchError}}</div><template v-else><button v-for="item in globalMatches" :key="item.lead.name" class="sr-item search-item" @click="chooseGlobal(item)"><strong>{{item.title}}</strong><span class="sr-cat">{{item.sub}}</span></button><div v-if="!globalMatches.length" class="sr-item">No matching permitted lead found.</div><div v-if="globalSearchMore" class="sr-item">More matches exist. Add part of the name or phone to narrow the results.</div></template></div></div></div><RouterLink id="cc-reports-link" :to="{name:'ccvisit'}">CC-Reports</RouterLink><div class="hdr-attend"><span class="att-io att-in">LIFE <b>PORTAL</b></span></div><div class="hdr-right"><div class="agent-info"><div class="an">{{session?.full_name||'Agent Name'}}</div><div class="ai">Call Center</div></div><div class="agent-avatar">{{String(session?.full_name||'A').slice(0,1).toUpperCase()}}</div></div></header>
  <div class="body-wrap"><nav class="sidebar"><div class="nav-section-label">Main</div><button class="nav-item" :class="{active:selectedView==='dashboard'}" @click="showView('dashboard')"><span class="ni">📊</span>Dashboard</button><button class="nav-item" :class="{active:selectedView==='queue'}" @click="showView('queue')"><span class="ni">📋</span>My Lead Queue <span class="nav-badge">{{total}}</span></button><button class="nav-item" :class="{active:selectedView==='followup'}" @click="showView('followup')"><span class="ni">📞</span>Lead Follow-Up Form</button><button class="nav-item" :class="{active:selectedView==='appointments'}" @click="showView('appointments')"><span class="ni">📅</span>Appointments</button><button class="nav-item" @click="openCreate"><span class="ni">➕</span>Add New Lead</button><button v-if="canManageLeads" class="nav-item" :class="{active:selectedView==='assign'}" @click="showView('assign')"><span class="ni">🔀</span>Assign Leads</button><button v-if="canManageLeads" class="nav-item" :class="{active:selectedView==='duplicates'}" @click="showView('duplicates')"><span class="ni">🧬</span>Duplicate Leads</button><button class="nav-item" :class="{active:selectedView==='worksheet'}" @click="showView('worksheet')"><span class="ni">📊</span>My Worksheet</button><div class="nav-section-label">Management (TL)</div><button class="nav-item" :class="{active:selectedView==='tl'}" @click="showView('tl')"><span class="ni">👥</span>TL Control Panel</button><button class="nav-item" :class="{active:selectedView==='reports'}" @click="showView('reports')"><span class="ni">📈</span>Reports</button><div class="nav-section-label">Knowledge Base</div><button class="nav-item" :class="{active:selectedView==='scripts'}" @click="showView('scripts')"><span class="ni">💬</span>Call Scripts</button><button class="nav-item" :class="{active:selectedView==='faq'}" @click="showView('faq')"><span class="ni">❓</span>FAQ / Knowledge Base</button><button class="nav-item" :class="{active:selectedView==='treatments'}" @click="showView('treatments')"><span class="ni">💉</span>Treatment Guide</button><button class="nav-item" :class="{active:selectedView==='objections'}" @click="showView('objections')"><span class="ni">🛡️</span>Objection Handling</button><button class="nav-item" :class="{active:selectedView==='branches'}" @click="showView('branches')"><span class="ni">🏥</span>Branch Directory</button><button class="nav-item" :class="{active:selectedView==='doctors'}" @click="showView('doctors')"><span class="ni">👨‍⚕️</span>Doctor Directory</button></nav><main class="main">
  <form v-if="['dashboard','queue','tl','reports','appointments','assign','duplicates'].includes(selectedView)" id="cc-quick-range" class="cc-rangebar" @submit.prevent="query='';apply()"><strong>📅 Lead Date Range</strong><button type="button" class="btn btn-sm cc-qr-btn" @click="quickRange('today')">Today</button><button type="button" class="btn btn-sm cc-qr-btn" @click="quickRange('yesterday')">Yesterday</button><button type="button" class="btn btn-sm cc-qr-btn" @click="quickRange('tomorrow')">Tomorrow</button><button type="button" class="btn btn-sm cc-qr-btn" @click="quickRange('month')">This Month</button><button type="button" class="btn btn-sm cc-qr-btn" @click="quickRange('nextmonth')">Next Month</button><button type="button" class="btn btn-sm cc-qr-btn" @click="quickRange('lastmonth')">Last Month</button><label>From <input v-model="from" type="date"></label><label>To <input v-model="to" type="date"></label><label>Filter <select id="cc-date-mode" v-model="mode"><option value="created">Created</option><option value="posting">Posting</option><option value="updated">Updated</option></select></label><button class="btn btn-g btn-sm cc-qr-btn" data-range="apply">Apply</button><button type="button" class="btn btn-gy btn-sm" @click="clearRange">Clear</button></form>
  <div class="page-breadcrumb">Home <span>›</span><span class="cur">{{({dashboard:'Dashboard',queue:'My Lead Queue',followup:'Lead Follow-Up Form',appointments:'Appointments',tl:'TL Control Panel',reports:'Reports',worksheet:'My Worksheet',assign:'Assign Leads',duplicates:'Duplicate Leads',scripts:'Call Scripts',faq:'FAQ / Knowledge Base',treatments:'Treatment Guide',objections:'Objection Handling',branches:'Branch Directory',doctors:'Doctor Directory'})[selectedView]||'Dashboard'}}</span><button v-if="['dashboard','queue','followup','tl','reports'].includes(selectedView)" class="btn btn-g btn-sm" @click="openCreate">＋ Add new lead</button></div>
  <form v-if="selectedView==='followup'&&!detail" class="cc-date-toolbar" @submit.prevent="apply"><strong>Lead Follow-Up Form</strong><input v-model="query" type="search" placeholder="Search client name, phone or lead ID"><button class="cc-primary">Find lead</button><button type="button" @click="showView('queue')">Back to queue</button></form>
  <p v-if="error" class="cc-error" role="alert">{{ error }} <button @click="load(page)">Retry</button></p>
  <div class="page-section active" :id="({dashboard:'page-dashboard',queue:'page-my-leads',followup:'page-followup',appointments:'page-appointment',tl:'page-tl-panel'})[selectedView]||'page-'+selectedView">
  <div v-if="selectedView==='dashboard'">
    <div class="stat-grid">
      <button class="stat-card s-blue" @click="openTile('assigned')"><div class="sl">{{from===today && to===today?'Assigned Today':'Assigned in range'}}</div><div class="sv">{{total}}</div><div class="ss">{{scoped?'Leads assigned to you':'All team leads in range'}} · click to view</div></button>
      <button class="stat-card s-gold" @click="openTile('untouched')"><div class="sl">Untouched</div><div class="sv">{{stageCounts.UNTOUCHED||0}}</div><div class="ss">Call now! · click to view</div></button>
      <button class="stat-card s-teal" @click="openTile('followup')"><div class="sl">Follow-Up Due</div><div class="sv">{{stageCounts['FOLLOW-UP']||0}}</div><div class="ss">Scheduled callbacks · click to view</div></button>
      <button class="stat-card s-gold" @click="openTile('norespnotreach')"><div class="sl">No Response / Not Reachable</div><div class="sv">{{noResponseCount}}</div><div class="ss">Combined · click to view</div></button>
      <button class="stat-card s-red" @click="openTile('invalid')"><div class="sl">Invalid</div><div class="sv">{{invalidCount}}</div><div class="ss">Invalid number · click to view</div></button>
      <button class="stat-card s-red" @click="openTile('nid')"><div class="sl">NID</div><div class="sv">{{nidCount}}</div><div class="ss">NID · click to view</div></button>
      <button class="stat-card s-green grp-card" @click="groupPanel=groupPanel==='appt'?'':'appt'"><div class="sl">Appointments ▾</div><div class="sv">{{appointmentRows.length}}</div><div class="ss">{{sameDayAppointments}} same-day · {{olderLeadAppointments}} older · tap to break down</div></button>
      <button class="stat-card s-teal grp-card" @click="groupPanel=groupPanel==='converted'?'':'converted'"><div class="sl">Converted ▾</div><div class="sv">{{convertedRows.length}}</div><div class="ss">{{sameDayConverted}} same-day · {{olderConverted}} older · tap to break down</div></button>
      <button class="stat-card s-red" @click="openTile('success')"><div class="sl">Conversion Rate</div><div class="sv">{{total?Math.round((stageCounts.SUCCESS||0)*100/total):0}}%</div><div class="ss">{{stageCounts.SUCCESS||0}} of {{total}} leads · click to view</div></button>
    </div>
    <div id="dash-group-panel" v-if="groupPanel" class="group-panel"><div class="stat-grid"><button v-for="item in (groupPanel==='appt'?[{kind:'appts',label:'Appointments Booked',sub:'Scheduled in range',val:appointmentRows.length},{kind:'apptsame',label:'Created & Appt Today',sub:'Same-day leads',val:sameDayAppointments},{kind:'apptdiff',label:'Older Lead, Appt Today',sub:'Older leads, appt today',val:olderLeadAppointments}]:[{kind:'converted',label:'Converted',sub:'Visited & booked',val:convertedRows.length},{kind:'convsame',label:'Created & Converted Today',sub:'Same-day leads',val:sameDayConverted},{kind:'convdiff',label:'Older Lead Converted',sub:'Older leads, converted',val:olderConverted}])" :key="item.label" class="stat-card s-green" @click="openTile(item.kind)"><div class="sl">{{item.label}}</div><div class="sv">{{item.val}}</div><div class="ss">{{item.sub}} · click to view</div></button></div></div>
    <div class="cc-grid-2" style="margin-bottom:16px">
      <section class="card"><header class="card-hdr">📋 My Lead Queue <span class="badge">{{rows.filter(x=>['UNTOUCHED','FOLLOW-UP'].includes(x.custom_cc_stage||x.status)).length}}</span><button class="btn btn-sm btn-gold" @click="showView('queue')">View All</button></header><div id="dash-queue-list" class="card-body"><div v-if="loading" class="cc-loading-row">Loading leads…</div><article v-for="row in dashQueueRows" :key="row.name" class="queue-item wf-qrow" tabindex="0" @click="openDetail(row)" @keydown.enter="openDetail(row)"><div class="wf-q-main"><div class="wf-q-l1"><strong class="wf-q-name">{{row.lead_name||row.name}}</strong><span class="wf-f br">🏥 {{row.branch||row.lead_assign_to_branch||'No branch'}}</span><span class="wf-f ag">👤 {{row.lead_owner||'Unassigned'}}</span><span class="wf-f st">{{row.custom_cc_stage||row.status}}</span><span v-if="row.custom_cc_sub_status" class="wf-f sub">{{row.custom_cc_sub_status}}</span><span v-if="row.custom_appointment_status" class="wf-f ap">{{row.custom_appointment_status}}</span><span v-if="row.custom_next_followup_date" class="wf-f fu">📅 {{row.custom_next_followup_date}}</span></div><div class="wf-q-l2">{{maskPhone(row.mobile_no)}}<template v-if="row.source"> · <b>{{row.source}}</b></template><template v-if="row.custom_treatment_interests"> · {{row.custom_treatment_interests}}</template></div></div><div class="wf-q-side"><button class="wf-q-btn" @click.stop="openDetail(row)">📞 Call &amp; Update</button></div></article><p v-if="!loading&&!error&&!dashQueueRows.length" class="cc-empty-state">No leads in queue. Great work! 🎉</p></div></section>
      <section class="card"><header class="card-hdr">⏰ Today’s Follow-Up Reminders <span class="badge">{{reminderRows.length}}</span></header><div id="dash-reminders" class="card-body"><template v-for="(bucket,key) in [{key:'overdue',label:'⚠️ Overdue',color:'#C62828'},{key:'today',label:'📅 Today',color:'#E65100'},{key:'upcoming',label:'⏭️ Upcoming',color:'#1565C0'},{key:'nodate',label:'❓ No date set',color:'#78909C'}]" :key="key"><div v-if="reminderBuckets[bucket.key].length" class="wf-reminder-group" :style="{background:bucket.color}"><span>{{bucket.label}}</span><b>{{reminderBuckets[bucket.key].length}}</b></div><article v-for="row in reminderBuckets[bucket.key]" :key="row.name" class="queue-item wf-qrow" tabindex="0" @click="openDetail(row)" @keydown.enter="openDetail(row)"><div class="wf-q-main"><div class="wf-q-l1"><strong class="wf-q-name">{{row.lead_name||row.name}}</strong><span class="wf-f st">{{row.custom_cc_stage||row.status}}</span><span v-if="row.custom_cc_sub_status" class="wf-f sub">{{row.custom_cc_sub_status}}</span><span v-if="row.custom_next_followup_date" class="wf-f fu">📅 {{row.custom_next_followup_date}}</span></div><div class="wf-q-l2">{{maskPhone(row.mobile_no)}} · {{row.custom_conclusion_remark||row.custom_cc_sub_status||'Follow-up scheduled'}}</div></div><div class="wf-q-side"><button class="wf-q-btn" @click.stop="openDetail(row)">Follow Up</button></div></article></template><p v-if="!loading&&!error&&!reminderRows.length" class="cc-empty-state">No reminders 👍</p></div></section>
    </div>
    <section v-if="!scoped" class="card"><header class="card-hdr">📊 Today’s Team Performance (TL View)</header><div class="card-body"><div class="tbl-wrap"><table><thead><tr><th>Agent</th><th>Assigned</th><th>Called</th><th>Appointments</th><th>Conversion %</th><th>Status</th></tr></thead><tbody><tr v-for="agent in agentRows" :key="agent.name"><td><strong>{{agent.name}}</strong></td><td>{{agent.total}}</td><td>{{agent.called}}</td><td>{{rows.filter(r=>r.lead_owner===agent.name&&r.custom_appointment_date_and_time).length}}</td><td>{{agent.total?Math.round(agent.success*100/agent.total):0}}%</td><td><span class="pill p-green">active</span></td></tr><tr v-if="!agentRows.length"><td colspan="6">No team data for this range.</td></tr></tbody></table></div></div></section>
  </div>
  <template v-else-if="selectedView==='queue'"><div class="cc-queue-toolbar"><span class="cc-status-line">{{ loading ? 'Loading leads…' : searching ? rows.length + ' matches on this page' : total + ' matching leads' }} · {{ applied }}<span v-if="scoped"> · Your assigned leads</span></span><span class="cc-quick-links"><button @click="load(page)">↻ Refresh</button></span></div><div id="cc-ml-filterbar" class="cc-queue-filters"><input id="cc-ml-search" aria-label="Filter loaded leads" v-model="queueSearch" type="search" placeholder="🔍 Search leads by name, phone or Lead ID"><select v-if="!scoped" id="cc-ml-owner" aria-label="Lead owner" v-model="queueOwner"><option value="">All Owners</option><option v-for="owner in [...new Set(rows.map(row=>row.lead_owner).filter(Boolean))]" :key="owner">{{owner}}</option></select><select id="cc-ml-status" aria-label="Lead status" v-model="queueStatus"><option value="">All Status</option><option>UNTOUCHED</option><option>FOLLOW-UP</option><option>SUCCESS</option><option>LOST</option><option>INVALID</option></select><select aria-label="Call result" v-model="queueSubStatus"><option value="">All Call Results</option><option>No Response / Not Reachable</option><option v-for="result in callOutcomes" :key="result">{{result}}</option></select><select aria-label="Treatment category" v-model="queueCategory"><option value="">All Categories</option><option v-for="category in treatmentCategories" :key="category">{{category}}</option></select><button class="btn btn-gy btn-sm" @click="matrixFilter=null;queueOwner='';queueStatus='';queueSubStatus='';queueCategory='';queueSearch=''">Clear</button></div><section class="card"><header class="card-hdr">📋 My Lead Queue <span class="badge">{{visibleLeads.length}}</span></header><div id="my-leads-list" class="card-body"><p class="cc-status-line">{{searching?'Search page '+page+' · '+visibleLeads.length+' matches on this page':'Showing '+(visibleLeads.length?(page-1)*10+1:0)+'–'+Math.min(page*10,visibleLeads.length)+' of '+visibleLeads.length+' leads'}}</p><article v-for="row in queuePageRows" :key="row.name" class="queue-item wf-qrow"><div class="wf-q-main"><div class="wf-q-l1"><strong class="wf-q-name">{{row.lead_name||row.name}}</strong><span class="wf-f ag">👤 {{row.lead_owner||'Unassigned'}}</span><span class="wf-f st">{{row.custom_cc_stage||row.status}}</span><span v-if="row.custom_cc_sub_status" class="wf-f sub">{{row.custom_cc_sub_status}}</span><small>{{row.name}}</small></div><div class="wf-q-l2">📞 {{maskPhone(row.mobile_no)}} · 📍 {{row.city||'—'}} · 📡 {{row.source||'—'}} · 🗓 {{String(row.creation||'').slice(0,10)}} · 📞×{{row.custom_call_count||0}}</div><div class="wf-q-l1"><span v-if="row.custom_treatment_interests" class="wf-f">{{row.custom_treatment_interests}}</span><span v-if="row.branch||row.lead_assign_to_branch" class="wf-f br">🏥 {{row.branch||row.lead_assign_to_branch}}</span><span v-if="row.custom_next_followup_date" class="wf-f fu">📅 {{row.custom_next_followup_date}}</span><span v-if="row.custom_appointment_date_and_time" class="wf-f ap">📅 Appt: {{row.custom_appointment_date_and_time}}</span></div><p v-if="row.custom_conclusion_remark" class="wf-q-l2">💬 {{row.custom_conclusion_remark}}</p></div><div class="wf-q-side"><button class="wf-q-btn" @click="openDetail(row)">📞 Call &amp; Update</button><button class="btn btn-gy btn-sm" @click="viewLead(row)">👁 View</button></div></article><p v-if="!loading&&!error&&!visibleLeads.length" class="cc-empty-state">No leads match the selected filter.</p></div></section><CCPager :page="page" :pages="pages" :busy="loading" @change="searching?load($event):page=$event" /></template>
  <template v-else-if="selectedView==='appointments'"><section class="cc-card"><header>📅 Appointments in selected date range <RouterLink :to="{name:'cc-appointments'}">Open booking calendar →</RouterLink></header><p class="cc-note">{{appointmentRows.length}} appointments found · summary is based on leads visible to your account.</p><div class="cc-report-metrics"><div v-for="(count,source) in sourceCounts" :key="source"><strong>{{count}}</strong><span>{{source}}</span></div></div><CCDataTable :columns="columns" :rows="appointmentRows" :busy="loading"><template #actions="{row}"><button @click="openDetail(row)">Open lead</button><RouterLink :to="{name:'cc-appointments',query:{lead:row.name}}">Book / reschedule</RouterLink></template></CCDataTable></section></template>
  <template v-else-if="selectedView==='assign'"><section class="cc-card"><header>🔀 Manual Lead Assignment <span>{{from}} → {{to}}</span></header><p class="cc-note">Tick leads in the selected date range, choose an owner, then apply. Date filter: {{mode}}.</p><div class="cc-queue-filters"><input v-model="assignSearch" placeholder="Search name / phone / owner"><select v-model="assignOwnerFilter"><option value="">All owners</option><option v-for="owner in assignOwners" :key="owner.id" :value="owner.id">{{owner.name}}</option></select><select v-model="assignStatusFilter"><option value="">All status</option><option v-for="stage in stages" :key="stage">{{stage}}</option></select><select v-model="assignEnquiryFilter"><option value="">All enquiries</option><option v-for="item in assignmentEnquiries" :key="item">{{item}}</option></select></div><p v-if="loading" role="status">Loading leads…</p><div class="tbl-wrap"><table class="cc-simple-table"><thead><tr><th><input type="checkbox" :checked="assignRows.length>0&&assignRows.every(row=>assignSelected.has(row.name))" aria-label="Select all filtered leads" @change="selectAllAssign($event.target.checked)"></th><th>Lead ID</th><th>Name</th><th>Phone</th><th>Area</th><th>Source</th><th>Owner</th><th>Status</th></tr></thead><tbody><tr v-for="row in assignRows" :key="row.name"><td><input type="checkbox" :checked="assignSelected.has(row.name)" @change="toggleAssignLead(row.name,$event.target.checked)"></td><td>{{row.name}}</td><td>{{row.lead_name||row.first_name}}</td><td>{{maskPhone(row.mobile_no)}}</td><td>{{row.city||'—'}}</td><td>{{row.source||'—'}}</td><td>{{row.lead_owner||'—'}}</td><td>{{row.custom_cc_stage||row.status}}</td></tr><tr v-if="!assignRows.length"><td colspan="8">No leads match this date range and filter.</td></tr></tbody></table></div><div class="cc-assign-sticky"><strong>{{assignSelected.size}} leads selected</strong><select v-model="assignTo"><option value="">Choose lead owner</option><option v-for="owner in assignOwners" :key="owner.id" :value="owner.id">{{owner.name}}</option></select><button class="cc-primary" :disabled="assignBusy" @click="applyManualAssignment">{{assignBusy?'Assigning…':'✅ Apply Assignment'}}</button></div><p v-if="assignError" class="cc-note">{{assignError}}</p></section><section class="cc-card"><header>⚡ Auto Transfer (Round Robin)</header><p class="cc-note">Spread every lead with a selected status across the available owners.</p><div class="cc-queue-filters"><select v-model="autoTransferStatus"><option value="">Select a status</option><option v-for="stage in stages" :key="stage">{{stage}}</option></select><strong>{{assignAutoRows.length}} matching leads</strong><button class="cc-primary" :disabled="assignBusy" @click="runAutoTransfer">{{assignBusy?'Transferring…':'🔀 Auto Transfer'}}</button></div><p>{{assignOwners.map(owner=>owner.name).join(' · ')||'No owners found in loaded range.'}}</p></section></template>
  <template v-else-if="selectedView==='duplicates'"><section class="cc-card"><header>🧬 Duplicate Leads <span>({{from}} → {{to}})</span><button class="cc-outline" :disabled="duplicateLoading" @click="loadDuplicateLeads">{{duplicateLoading?'Loading…':'↻ Refresh'}}</button></header><p class="cc-note">Duplicate submissions in the selected date range. Find Original searches the lead by mobile number.</p><div class="cc-queue-filters"><input v-model="duplicateSearch" type="search" placeholder="Search name, phone or enquiry"><span>{{duplicateFiltered.length}} duplicate records</span></div><p v-if="duplicateLoading" role="status">Loading duplicate submissions…</p><p v-if="duplicateError" class="cc-error" role="alert">{{duplicateError}}</p><div class="tbl-wrap"><table class="cc-simple-table"><thead><tr><th>Name</th><th>Phone</th><th>Enquired For</th><th>Created</th><th>Action</th></tr></thead><tbody><tr v-for="row in duplicateVisible" :key="row.name"><td>{{row.name1||'—'}}</td><td>{{maskPhone(row.phone)}}</td><td>{{row.enquired_for||'—'}}</td><td>{{String(row.creation||'').slice(0,16)}}</td><td><button class="cc-primary" @click="openDuplicateLead(row)">Find Original</button></td></tr><tr v-if="!duplicateLoading&&!duplicateError&&!duplicateVisible.length"><td colspan="5">No duplicate leads in this date range.</td></tr></tbody></table></div><div class="cc-pager-row"><button :disabled="duplicatePage<=1" @click="duplicatePage--">Previous</button><span>Page {{duplicatePage}} of {{duplicatePages}}</span><button :disabled="duplicatePage>=duplicatePages" @click="duplicatePage++">Next</button></div></section></template>
  <template v-else-if="selectedView==='worksheet'"><CCWorksheet /></template>
  <template v-else-if="selectedView==='tl'">
    <section class="cc-card tl-control-panel"><header>👥 Team lead control panel <button class="cc-outline" :disabled="tlConfigBusy" @click="loadTlConfig">{{tlConfigBusy?'Loading…':'Refresh team status'}}</button></header>
      <p class="cc-note">Live team totals for the selected date range. Assignment settings and preview follow the existing Team Lead permissions.</p>
      <div class="cc-dashboard-tiles cc-stage-tiles"><button @click="queueStatus='';showView('queue')"><small>TOTAL LEADS (ALL)</small><strong>{{total}}</strong><span>View master list</span></button><button @click="openTile('untouched')"><small>UNTOUCHED</small><strong>{{stageCounts.UNTOUCHED||0}}</strong></button><button @click="openTile('success')"><small>SUCCESS</small><strong>{{stageCounts.SUCCESS||0}}</strong></button><button @click="queueStatus='INVALID';showView('queue')"><small>INVALID</small><strong>{{stageCounts.INVALID||0}}</strong></button><button v-for="stage in ['FOLLOW-UP','LOST']" :key="stage" @click="queueStatus=stage;showView('queue')"><small>{{stage}}</small><strong>{{stageCounts[stage]||0}}</strong><span>Open matching leads →</span></button></div>
      <section class="tl-inner-section"><header>📊 Agent Status</header><p v-if="loading" class="cc-note">Loading team leads…</p><div class="tbl-wrap"><table class="cc-simple-table"><thead><tr><th>Agent</th><th>ID</th><th>Role</th><th>Status</th><th>Conv Rate</th><th>Assigned Leads</th><th>Calls</th><th>Appts</th></tr></thead><tbody><tr v-for="agent in agentRows" :key="agent.name"><td><strong>{{agent.name}}</strong></td><td>{{tlConfig?.agents?.find(item=>item.agent===agent.name)?.employee||'—'}}</td><td>{{tlConfig?.agents?.find(item=>item.agent===agent.name)?.designation||'—'}}</td><td><span class="pill p-green">{{tlConfig?.agents?.find(item=>item.agent===agent.name)?.checked_in?'active':'—'}}</span></td><td><div class="cc-conversion-meter"><span :style="{width:(agent.total?Math.round(agent.success*100/agent.total):0)+'%'}"></span></div>{{agent.total?Math.round(agent.success*100/agent.total):0}}%</td><td>{{agent.total}}</td><td>{{rows.filter(r=>r.lead_owner===agent.name&&(Number(r.custom_call_count)||0)>0).length}}</td><td>{{rows.filter(r=>r.lead_owner===agent.name&&r.custom_appointment_date_and_time).length}}</td></tr><tr v-if="!agentRows.length"><td colspan="8">No team leads in the selected range.</td></tr></tbody></table></div></section>
      <section class="tl-inner-section"><header>⚙️ Lead Assignment Settings <span v-if="tlConfig">{{tlConfig.settings?.assignment_mode||'Manual'}} assignment · {{tlConfig.today}}</span></header><p v-if="tlConfigBusy" role="status">Loading authorized assignment settings…</p><p v-if="tlConfigError" class="cc-error" role="alert">{{tlConfigError}}</p><template v-if="tlConfig"><CCAssignmentControls :config="tlConfig" /><div class="tl-settings-grid"><div><small>Assignment hours</small><strong>{{tlConfig.settings?.start_time||'—'}} – {{tlConfig.settings?.end_time||'—'}}</strong></div><div><small>Open check-in required</small><strong>{{tlConfig.settings?.require_checkin?'Yes':'No'}}</strong></div><div><small>Source mapping required</small><strong>{{tlConfig.settings?.require_source_mapping?'Yes':'No'}}</strong></div><div><small>Conversion window</small><strong>{{tlConfig.settings?.conversion_window_days||30}} days</strong></div><div><small>Keep unassigned</small><strong>{{tlConfig.settings?.keep_unassigned?'Yes':'No'}}</strong></div></div><div class="tl-preview"><label>Preview automatic assignment<select v-model="tlPreviewSource"><option value="">Select lead source</option><option v-for="source in tlConfig.source_options||[]" :key="source" :value="source">{{source}}</option></select></label><button class="cc-primary" :disabled="tlPreviewBusy" @click="previewTlAssignment">{{tlPreviewBusy?'Checking eligibility…':'Preview assignment'}}</button></div><p v-if="tlPreviewError" class="cc-error" role="alert">{{tlPreviewError}}</p><div v-if="tlPreview" class="tl-preview-result"><strong>{{tlPreview.recommended_agent?'Recommended: '+tlPreview.recommended_agent.employee_name:'No eligible agent for this source right now'}}</strong><span>{{tlPreview.eligible_agents}} of {{tlPreview.configured_agents}} eligible · {{tlPreview.assignment_mode}} mode · {{tlPreview.assignment_start_time}}–{{tlPreview.assignment_end_time}}</span><div class="tbl-wrap"><table class="cc-simple-table"><thead><tr><th>Agent</th><th>Status</th><th>Check-in</th><th>Assigned today</th><th>Conversion</th><th>Eligibility</th><th>Reason</th></tr></thead><tbody><tr v-for="agent in tlPreview.agents||[]" :key="agent.agent"><td>{{agent.employee_name}}</td><td>{{agent.auto_enabled?'Auto on':'Auto off'}}<span v-if="agent.temporarily_stopped"> · Stopped</span></td><td>{{agent.checked_in?'Checked in':'No open check-in'}}</td><td>{{agent.today_assigned}}{{agent.max_per_day?' / '+agent.max_per_day:''}}</td><td>{{agent.conversion_rate}}%</td><td>{{agent.eligible?'Eligible':'Unavailable'}}</td><td>{{(agent.reasons||[]).join(' · ')||'Ready'}}</td></tr></tbody></table></div></div><div class="tbl-wrap" v-if="!tlPreview"><table class="cc-simple-table"><thead><tr><th>Configured agent</th><th>Role</th><th>Branch</th><th>Lead sources</th><th>Today</th><th>Check-in</th><th>Assignment</th></tr></thead><tbody><tr v-for="agent in tlConfig.agents||[]" :key="agent.agent"><td>{{agent.employee_name}}</td><td>{{agent.designation||'—'}}</td><td>{{agent.branch||'—'}}</td><td>{{(agent.allowed_sources||[]).join(', ')||'All / not mapped'}}</td><td>{{agent.today_assigned}}</td><td>{{agent.checked_in?'Open':'—'}}</td><td>{{agent.auto_enabled?'Enabled':'Manual'}}<span v-if="agent.temporarily_stopped"> · Paused</span></td></tr><tr v-if="!tlConfig.agents?.length"><td colspan="7">No assignment agents are configured for this account.</td></tr></tbody></table></div></template></section>
      <section class="tl-inner-section"><header>📋 All Leads Master List <button class="cc-outline" @click="printReport">🖨️ Print</button></header><div class="cc-queue-filters"><input v-model="tlSearch" placeholder="Search name / phone / owner…"><select v-model="tlOwner" @change="tlPage=1"><option value="">All Owners</option><option v-for="owner in assignOwners" :key="owner.id" :value="owner.id">{{owner.name}}</option></select><select v-model="tlStatus" @change="tlPage=1"><option value="">All Status</option><option v-for="stage in stages" :key="stage">{{stage}}</option></select></div><div class="tbl-wrap"><table class="cc-simple-table"><thead><tr><th>Lead ID</th><th>Name</th><th>Phone</th><th>Area</th><th>Source</th><th>Category</th><th>Assigned To</th><th>Status</th><th>Calls</th><th>Date</th><th>Next FU</th><th>Action</th></tr></thead><tbody><tr v-for="row in tlVisible" :key="row.name"><td>{{row.name}}</td><td><strong>{{row.lead_name||row.first_name}}</strong></td><td>{{maskPhone(row.mobile_no)}}</td><td>{{row.city||'—'}}</td><td>{{row.source||'—'}}</td><td>{{row.custom_treatment_interests||row.enquired_for||'—'}}</td><td>{{row.lead_owner||'—'}}</td><td>{{row.custom_cc_stage||row.status}}</td><td>{{row.custom_call_count||0}}</td><td>{{String(row.creation||'').slice(0,10)}}</td><td>{{row.custom_next_followup_date||'—'}}</td><td><button @click="viewLead(row)">Open</button></td></tr><tr v-if="!tlVisible.length"><td colspan="12">No leads match the selected filters.</td></tr></tbody></table></div><div class="cc-pager-row"><button :disabled="tlPage<=1" @click="tlPage--">Previous</button><span>Page {{tlPage}} of {{tlPages}} · {{tlFiltered.length}} leads</span><button :disabled="tlPage>=tlPages" @click="tlPage++">Next</button></div></section>
    </section>
  </template>
  <template v-else-if="selectedView==='reports'"><div class="cc-dashboard-tiles cc-stage-tiles"><button v-for="stage in stages" :key="stage" @click="queueStatus=stage;showView('queue')"><small>{{stage}}</small><strong>{{stageCounts[stage]}}</strong><span>{{rows.length?Math.round(stageCounts[stage]*100/rows.length):0}}% of visible leads · open leads</span></button><button><small>TOTAL LEADS</small><strong>{{total}}</strong><span>{{applied}}</span></button><button><small>APPOINTMENTS</small><strong>{{appointmentRows.length}}</strong><span>In selected range</span></button></div>
    <section class="cc-card"><header>📊 Lead Status Summary <button class="cc-outline" @click="printReport">🖨️ Print Report</button></header><div class="cc-dashboard-tiles cc-stage-tiles"><button v-for="stage in stages" :key="stage" @click="queueStatus=stage;showView('queue')"><small>{{stage}}</small><strong>{{stageCounts[stage]||0}}</strong></button></div><div class="cc-dashboard-columns"><section class="tl-inner-section"><header>By Treatment Category</header><table class="cc-simple-table"><thead><tr><th>Category</th><th>Leads</th><th>%</th></tr></thead><tbody><tr v-for="[category,count] in categoryCounts" :key="category"><td>{{category}}</td><td>{{count}}</td><td>{{total?Math.round(count*100/total):0}}%</td></tr><tr v-if="!categoryCounts.length"><td colspan="3">No category data.</td></tr></tbody></table></section><section class="tl-inner-section"><header>By Lead Source (Top 10)</header><table class="cc-simple-table"><thead><tr><th>Source</th><th>Leads</th></tr></thead><tbody><tr v-for="[source,count] in sourceCounts" :key="source"><td>{{source}}</td><td>{{count}}</td></tr><tr v-if="!sourceCounts.length"><td colspan="2">No source data.</td></tr></tbody></table></section></div></section>
    <section class="cc-card"><header>📅 Appointments Report <span>{{appointmentRows.length}} appointments in range</span></header><div class="tbl-wrap"><table class="cc-simple-table"><thead><tr><th>Agent</th><th>Appointments Booked</th><th>Visited Booked</th><th>Visited Not Booked</th><th>Total Visited</th><th>Not Visited</th><th>Pending</th><th>Converted</th><th>Conversion %</th><th>Billed</th><th>Paid</th><th>Preferred Branch</th></tr></thead><tbody><tr v-for="agent in appointmentAgentRows" :key="agent.key"><td><strong>{{agent.name}}</strong></td><td>{{agent.booked}}</td><td>{{agent.vb}}</td><td>{{agent.vnb}}</td><td>{{agent.visited}}</td><td>{{agent.nv}}</td><td>{{agent.pending+agent.cancelled}}</td><td>{{agent.converted}}</td><td>{{agent.rate}}%</td><td>{{money(agent.billed)}}</td><td>{{money(agent.paid)}}</td><td>{{agent.preferredBranch}}</td></tr><tr v-if="!appointmentAgentRows.length"><td colspan="12">No appointments in the selected range.</td></tr></tbody></table></div><p class="cc-note">Converted means portal status Converted or an appointment marked Visited Booked. Billed and Paid totals use the Call Centre invoice report.</p><CCDataTable :columns="columns" :rows="appointmentRows" :busy="loading"><template #actions="{row}"><button @click="openDetail(row)">Open lead</button><RouterLink :to="{name:'cc-appointments',query:{lead:row.name}}">View booking</RouterLink></template></CCDataTable></section>
    <div class="cc-dashboard-columns"><section class="cc-card"><header>📊 Lead source report</header><table class="cc-simple-table"><thead><tr><th>Source</th><th>Leads</th><th>Share</th></tr></thead><tbody><tr v-for="[source,count] in sourceCounts" :key="source"><td>{{source}}</td><td>{{count}}</td><td>{{rows.length?Math.round(count*100/rows.length):0}}%</td></tr><tr v-if="!sourceCounts.length"><td colspan="3">No source data in this date range.</td></tr></tbody></table></section>
    <section class="cc-card"><header>📑 Source-wise Appointment &amp; Revenue Report</header><template v-if="canViewSourceReports"><p class="cc-note">Appointment and invoice values follow your report permissions and the selected date range.</p><div class="tbl-wrap"><table class="cc-simple-table"><thead><tr><th>Source</th><th>Leads</th><th>Appointments</th><th>Converted</th><th>Conversion %</th><th>Billed</th><th>Paid</th></tr></thead><tbody><tr v-for="[source,count] in sourceCounts" :key="source"><td>{{source}}</td><td>{{count}}</td><td>{{appointmentRows.filter(row=>(row.source||row.custom_media||'Unknown')===source).length}}</td><td>{{appointmentRows.filter(row=>(row.source||row.custom_media||'Unknown')===source&&(row.status==='Converted'||row.custom_appointment_status==='Visited Booked')).length}}</td><td>{{appointmentRows.filter(row=>(row.source||row.custom_media||'Unknown')===source).length?Math.round(appointmentRows.filter(row=>(row.source||row.custom_media||'Unknown')===source&&(row.status==='Converted'||row.custom_appointment_status==='Visited Booked')).length*100/appointmentRows.filter(row=>(row.source||row.custom_media||'Unknown')===source).length):0}}%</td><td>{{money(visibleSalesRows.filter(row=>row.source===source).reduce((sum,row)=>sum+Number(row.with_gst??row.grand_total??0),0))}}</td><td>{{money(visibleSalesRows.filter(row=>row.source===source).reduce((sum,row)=>sum+Number(row.paid_with_gst??row.paid_amount??row.paid??0),0))}}</td></tr><tr v-if="!sourceCounts.length"><td colspan="7">No source report rows.</td></tr></tbody></table></div></template><div v-else class="cc-access-restricted">🔒 Access Restricted — this report is available to Team Leads and Managers.</div></section>
    <section class="cc-card"><header>🏥 Branch performance</header><table class="cc-simple-table"><thead><tr><th>Branch</th><th>Leads</th><th>Success</th></tr></thead><tbody><tr v-for="branch in [...new Set(rows.map(r=>r.branch||r.lead_assign_to_branch||'Unassigned'))]" :key="branch"><td>{{branch}}</td><td>{{rows.filter(r=>(r.branch||r.lead_assign_to_branch||'Unassigned')===branch).length}}</td><td>{{rows.filter(r=>(r.branch||r.lead_assign_to_branch||'Unassigned')===branch&&(r.custom_cc_stage||r.status)==='SUCCESS').length}}</td></tr></tbody></table></section>
    <section class="cc-card"><header>🏷️ Lead sub-status</header><table class="cc-simple-table"><thead><tr><th>Sub-status</th><th>Leads</th><th>Share</th></tr></thead><tbody><tr v-for="[status,count] in subStatusCounts" :key="status"><td>{{status}}</td><td>{{count}}</td><td>{{rows.length?Math.round(count*100/rows.length):0}}%</td></tr><tr v-if="!subStatusCounts.length"><td colspan="3">No sub-status data.</td></tr></tbody></table></section>
    <section class="cc-card"><header>🧴 Treatment category</header><table class="cc-simple-table"><thead><tr><th>Category</th><th>Leads</th><th>Share</th></tr></thead><tbody><tr v-for="[category,count] in categoryCounts" :key="category"><td>{{category}}</td><td>{{count}}</td><td>{{rows.length?Math.round(count*100/rows.length):0}}%</td></tr><tr v-if="!categoryCounts.length"><td colspan="3">No treatment categories recorded.</td></tr></tbody></table></section>
    <section v-for="[field,title] in [['source','Source'],['lead_owner','Agent'],['branch','Branch']]" :key="field" class="cc-card"><header>{{title}} × Sub-Status — Lead Count <button class="cc-outline" :disabled="loading || incomplete || searching" @click="exportMatrixCsv(field)">⬇️ CSV</button><button class="cc-outline" @click="printReport">🖨️ Print</button></header><p class="cc-note">Columns are sub-statuses · click any count to view matching leads.</p><div class="tbl-wrap"><table class="cc-simple-table"><thead><tr><th>{{title}}</th><th v-for="status in matrixStatuses" :key="status">{{status}}</th><th>Total</th></tr></thead><tbody><tr v-for="item in matrixRows(field)" :key="item.key"><td>{{item.key}}</td><td v-for="status in matrixStatuses" :key="status"><button v-if="item.counts[status]" class="cc-report-click" @click="openMatrixCell(field,item.key,status)">{{item.counts[status]}}</button><span v-else>·</span></td><td><button class="cc-report-click" @click="openMatrixCell(field,item.key,'')">{{item.total}}</button></td></tr><tr v-if="rows.length"><th>Total</th><th v-for="status in matrixStatuses" :key="status">{{rows.filter(row=>(row.custom_cc_sub_status||'(none)')===status).length}}</th><th>{{rows.length}}</th></tr><tr v-if="!rows.length"><td colspan="99">No report rows.</td></tr></tbody></table></div></section></div>
    <section class="cc-card"><header>📈 Pipeline — Leads &amp; Dates <span>{{pipelineRows.length}} in pipeline</span></header><CCDataTable :columns="columns" :rows="pipelineRows" :busy="loading"><template #actions="{row}"><button @click="openDetail(row)">Open lead</button></template></CCDataTable></section>
    <section class="cc-card"><header>🧾 Lead report <button @click="printReport">Print report</button></header><CCDataTable :columns="columns" :rows="rows" :busy="loading" /></section>
    <section class="cc-card cc-sales-report"><header>💳 Call Centre Sales Report <button class="cc-outline" :disabled="salesBusy" @click="loadSales">{{salesBusy?'Loading…':'Refresh sales report'}}</button></header><p class="cc-note">Call Centre invoices in {{from}} – {{to}}. Invoice rows use the existing permission-checked report API.</p><p v-if="salesError" class="cc-error" role="alert">{{salesError}} <button @click="loadSales">Retry</button></p><p v-if="salesBusy" role="status">Loading invoice and payment totals…</p><template v-if="salesData"><div class="cc-sales-kpis"><div><small>Total billed</small><strong>{{money(visibleSalesSummary.with_gst)}}</strong></div><div><small>Revenue collected</small><strong>{{money(visibleSalesSummary.paid)}}</strong></div><div><small>Outstanding</small><strong>{{money(visibleSalesSummary.balance)}}</strong></div><div><small>Invoices</small><strong>{{visibleSalesSummary.invoice_count}}</strong></div></div><section class="tl-inner-section"><header>Agent-wise Sales</header><div class="tbl-wrap"><table class="cc-simple-table"><thead><tr><th>Agent</th><th>Invoices</th><th>Billed</th><th>Paid</th><th>Outstanding</th><th>Revenue share</th></tr></thead><tbody><tr v-for="agent in salesAgentRows" :key="agent.name"><td>{{agent.name}}</td><td>{{agent.count}}</td><td>{{money(agent.billed)}}</td><td>{{money(agent.paid)}}</td><td>{{money(agent.balance)}}</td><td>{{visibleSalesSummary.paid?Math.round(agent.paid*100/visibleSalesSummary.paid):0}}%</td></tr><tr v-if="!salesAgentRows.length"><td colspan="6">No Call Centre invoices in this period.</td></tr></tbody></table></div></section><section class="tl-inner-section"><header>🧾 Invoice-wise Sales <input v-model="salesSearch" type="search" placeholder="Search client, owner, branch or invoice"></header><div class="tbl-wrap"><table class="cc-simple-table"><thead><tr><th>Invoice</th><th>Client / Lead</th><th>Agent</th><th>Branch</th><th>Date</th><th>Billed</th><th>Paid</th><th>Outstanding</th></tr></thead><tbody><tr v-for="row in salesFilteredRows" :key="row.invoice"><td>{{row.invoice}}</td><td>{{row.lead_name||row.customer||row.lead||'—'}}</td><td>{{salesOwnerName(row)||'—'}}</td><td>{{row.branch||row.lead_branch||'—'}}</td><td>{{row.invoice_date||'—'}}</td><td>{{money(row.with_gst)}}</td><td>{{money(row.paid_with_gst??row.paid)}}</td><td>{{money(row.balance)}}</td></tr><tr v-if="!salesFilteredRows.length"><td colspan="8">No matching invoices.</td></tr></tbody></table></div></section><section class="tl-inner-section"><header>🧾 Lead-wise Sales (per client) <input v-model="salesClientSearch" type="search" placeholder="Search client / owner" @input="salesClientPage=1"></header><div class="tbl-wrap"><table class="cc-simple-table"><thead><tr><th>#</th><th>Client / Lead</th><th>Last Invoice</th><th>Invoices</th><th>Total Billed</th><th>Revenue</th><th>Outstanding</th></tr></thead><tbody><tr v-for="(row,index) in salesClientVisible" :key="row.key"><td>{{(salesClientPage-1)*10+index+1}}</td><td><strong>{{row.label}}</strong></td><td>{{row.lastInvDate||'—'}}</td><td>{{row.count}}</td><td>{{money(row.billed)}}</td><td>{{money(row.paid)}}</td><td>{{money(row.outstanding)}}</td></tr><tr v-if="!salesClientVisible.length"><td colspan="7">No matching client sales.</td></tr></tbody></table></div><div class="cc-pager-row"><button :disabled="salesClientPage<=1" @click="salesClientPage--">Previous</button><span>Page {{salesClientPage}} of {{salesClientPages}}</span><button :disabled="salesClientPage>=salesClientPages" @click="salesClientPage++">Next</button></div></section></template></section>
  </template>
  <template v-else-if="selectedView==='scripts'"><section id="scripts-area" class="card"><header class="card-hdr">💬 Call Centre Agent Scripts — Master Reference</header><div class="card-body"><div id="script-tabs" class="tab-nav"><button v-for="tab in [{id:'scripts',label:'📋 Call Scripts'},{id:'objections',label:'🛡️ Objection Handling'},{id:'results',label:'📈 Results FAQ'}]" :key="tab.id" class="tab-btn" :class="{on:knowledgeTab===tab.id}" @click="knowledgeTab=tab.id">{{tab.label}}</button></div><div v-if="knowledgeTab==='scripts'" id="tab-scripts" class="tab-pane on"><article v-for="item in scripts" :key="item.title" class="script-card"><div class="sc-title">{{item.icon}} {{item.title}}</div><div class="sc-text" style="white-space:pre-line">{{item.text}}</div><button class="copy-btn" @click="copyText(item.text)">📋 Copy Script</button></article></div><div v-else-if="knowledgeTab==='objections'" id="tab-objections" class="tab-pane on"><details v-for="item in objections" :key="item.obj" class="acc-item"><summary class="acc-hdr">🛡️ Client says: “{{item.obj}}”<span class="acc-icon">▼</span></summary><div class="acc-body"><div class="script-card"><div class="sc-title">Suggested Response</div><div class="sc-text" style="white-space:pre-line">{{item.response}}</div><div class="agent-tip">💡 <strong>Strategy:</strong> {{item.tip}}</div><button class="copy-btn" @click="copyText(item.response)">📋 Copy Response</button></div></div></details></div><div v-else id="tab-results" class="tab-pane on"><div class="script-card"><div class="sc-title">Golden Rule of Results</div><div class="sc-text">Never give a single, rigid number. Instead, explain the timeline and emphasize customization. Frame the variation as a sign of premium medical care.</div></div><details v-for="item in faqs.filter(x=>/result/i.test(x.cat+' '+x.q))" :key="item.q" class="acc-item"><summary class="acc-hdr">{{item.cat}}: {{item.q}}<span class="acc-icon">▼</span></summary><div class="acc-body">{{item.a}}<button class="copy-btn" @click="copyText(item.a)">📋 Copy Answer</button></div></details></div></div></section><p v-if="copyNotice" class="cc-success">{{copyNotice}}</p></template>
  <template v-else-if="selectedView==='faq'"><section id="faq-area" class="card"><header class="card-hdr">❓ FAQ &amp; Knowledge Base<input id="faq-search" v-model="faqSearch" placeholder="Search FAQs..." class="ff-input" style="width:200px;height:28px"></header><div class="card-body"><div id="faq-list"><section v-for="category in [...new Set(filteredFaqs.map(item=>item.cat))]" :key="category" style="margin-bottom:14px"><div class="form-section-title">{{category}}</div><details v-for="item in filteredFaqs.filter(item=>item.cat===category)" :key="item.q" class="acc-item"><summary class="acc-hdr">{{item.q}}<span class="acc-icon">▼</span></summary><div class="acc-body"><p>{{item.a}}</p><button class="copy-btn" @click="copyText(item.a)">📋 Copy Answer</button></div></details></section></div></div></section></template>
  <template v-else-if="selectedView==='treatments'"><section id="treatments-area" class="card"><header class="card-hdr">💉 Treatment Knowledge Base</header><div class="card-body"><details v-for="item in treatments" :key="item.name" class="acc-item"><summary class="acc-hdr">{{item.icon}} {{item.name}}<span class="pill p-blue">{{item.cat}}</span><span class="acc-icon">▼</span></summary><div class="acc-body"><div class="form-grid"><div><div class="form-section-title">Purpose</div><p>{{item.purpose}}</p></div><div><div class="form-section-title">Suitable For</div><p>{{item.suitableFor}}</p></div></div><div class="form-section-title">Benefits</div><p v-for="benefit in item.benefits" :key="benefit">{{benefit}}</p><div class="form-grid"><p><b>Sessions:</b> {{item.sessions}}</p><p><b>Recovery:</b> {{item.recovery}}</p><p><b>Pain Level:</b> {{item.pain}}</p><p><b>Results:</b> {{item.results}}</p></div><p><b>Cannot take:</b> <span style="color:#c00000">{{item.cannotTake}}</span></p><h4>FAQs:</h4><div v-for="faq in item.faq" :key="faq.q" class="script-card"><b>{{faq.q}}</b><p>{{faq.a}}</p></div></div></details></div></section></template>
  <template v-else-if="selectedView==='objections'"><section id="objections-area" class="card"><header class="card-hdr">🛡️ Objection Handling Guide</header><div class="card-body"><details v-for="item in objections" :key="item.obj" class="acc-item"><summary class="acc-hdr">🛡️ “{{item.obj}}”<span class="acc-icon">▼</span></summary><div class="acc-body"><div class="script-card"><div class="sc-title">✅ Recommended Response</div><div class="sc-text" style="white-space:pre-line">{{item.response}}</div><div class="agent-tip">💡 <strong>Key Strategy:</strong> {{item.tip}}</div><button class="copy-btn" @click="copyText(item.response)">📋 Copy</button></div></div></details></div></section></template>
  <template v-else-if="selectedView==='branches'"><section id="branches-area" class="card"><header class="card-hdr">🏥 Branch Directory — All Branches<button class="btn btn-gy btn-sm" :disabled="doctorLoading" @click="loadDoctors">↻ Refresh</button></header><div class="card-body"><p v-if="doctorLoading" role="status">Loading branch contacts…</p><p v-if="doctorError" class="cc-error" role="alert">{{doctorError}}</p><div class="cc-legacy-branch-grid"><article v-for="branch in branches" :key="branch.code" class="form-section"><div class="form-section-title">🏥 {{branch.name}} ({{branch.code}}) — {{branch.city}}</div><div class="cc-branch-details"><div>📍 {{branch.address}}</div><div>📞 {{branch.phone}}</div><div>🕐 {{branch.hours}}</div><div>👤 Center Manager: <strong>{{branchManager(branch.name)}}</strong></div><div>👥 ACM: <strong>{{branchManager(branch.name,true)}}</strong></div></div><div class="btn-row"><a class="btn btn-teal btn-sm" :href="branch.maps" target="_blank" rel="noopener">🗺️ Open Maps</a><button class="copy-btn" @click="copyText(`${branch.name} (${branch.city})\n${branch.address}\n${branch.phone}\n${branch.hours}\n${branch.maps}`)">📋 Copy Location + Map Link</button></div></article></div></div></section><p v-if="copyNotice" class="cc-success" role="status">{{copyNotice}}</p></template>
  <template v-else-if="selectedView==='doctors'"><section id="doctors-area" class="card"><header class="card-hdr">👨‍⚕️ Doctor Directory <span class="badge">{{doctorRows.length}}</span><button class="btn btn-gy btn-sm" :disabled="doctorLoading" @click="loadDoctors">↻ Refresh</button></header><div class="card-body"><p v-if="doctorLoading" role="status">Loading doctor directory…</p><p v-if="doctorError" class="cc-error" role="alert">{{doctorError}}</p><section v-for="branch in doctorBranches" :key="branch" class="cc-doctor-branch"><div class="form-section-title">🏥 {{branch}} ({{doctorRows.filter(row=>(row.branch||'Head Office / Unassigned')===branch).length}})</div><div class="tbl-wrap"><table><thead><tr><th>Doctor</th><th>Designation</th><th>Contact</th><th>Emp ID</th></tr></thead><tbody><tr v-for="doctor in doctorRows.filter(row=>(row.branch||'Head Office / Unassigned')===branch)" :key="doctor.name"><td><strong>{{doctor.employee_name}}</strong></td><td><span class="pill" :class="({'Chief HT Surgeon':'p-red','HOD Hair transplant surgery':'p-red','Consultant Doctor':'p-gold',Doctor:'p-blue','Assistant Doctor':'p-teal',Dermatologist:'p-green'})[doctor.designation]||'p-gy'">{{doctor.designation}}</span></td><td>{{doctor.cell_number||'—'}}</td><td class="cc-employee-id">{{doctor.name}}</td></tr></tbody></table></div></section><p v-if="!doctorLoading&&!doctorRows.length" class="cc-empty-state">Doctor data not available for this login.</p></div></section></template>
  <template v-else-if="selectedView==='followup'&&!detail"><p class="cc-status-line">{{loading?'Searching…':rows.length?'Select the client to start the follow-up form.':'Search by mobile number, client name or Lead ID.'}}</p><CCDataTable :columns="columns" :rows="rows" :busy="loading"><template #actions="{row}"><button class="cc-primary" @click="openDetail(row)">Open Follow-Up Form</button></template></CCDataTable><CCPager :page="page" :pages="pages" :busy="loading" @change="load" /></template>
  <template v-else-if="selectedView==='followup'&&detail"><p v-if="detailLoading" role="status">Loading lead…</p><p v-else-if="detailError" class="cc-error" role="alert">{{detailError}}</p><CCLeadWorksheet v-else :lead="detail" :manager="contactManager" :busy="savingFollowup" :error="actionError" :notice="actionNotice" v-model:draft="leadDraft" v-model:followup="followup" v-model:categories="selectedCategories" v-model:interests="selectedInterests" @save="saveFollowup" @back="closeDetail" @start-call="startCall" @stop-call="openPhone" /></template>
  </div></main></div>
  <CCConsultationBooking ref="booking" @saved="appointmentSaved" />
  <dialog ref="tileDialog" class="modal-box cc-summary-modal" aria-labelledby="cc-tile-title"><h2 id="cc-tile-title" class="modal-title">{{tileTitle}} ({{tileRows.length}})</h2><article v-for="row in tileRows" :key="row.name" class="queue-item"><div><div class="qi-name">{{row.lead_name||row.name}}</div><div class="qi-sub">{{maskPhone(row.mobile_no)}} | {{row.city||'—'}} | {{row.custom_cc_stage||row.status}}</div><div class="qi-sub">👤 {{row.lead_owner||'Unassigned'}}</div><div class="qi-tags"><span class="pill p-green">{{row.custom_appointment_status||'Pending'}}</span><span v-if="row.custom_next_followup_date" class="pill p-gold">📅 {{row.custom_next_followup_date}}</span></div></div><button class="btn btn-n btn-sm" @click="tileDialog.close();openDetail(row)">Open</button></article><p v-if="!tileRows.length" class="cc-empty-state">No leads in this category.</p><div class="btn-row"><button class="btn btn-gy btn-sm" @click="tileDialog.close()">Close</button></div></dialog>
  <dialog ref="dialog" class="modal-box cc-summary-modal"><template v-if="summaryLead"><h2 class="modal-title">Lead Summary — {{summaryLead.lead_name||summaryLead.name}}</h2><div class="form-section">👤 Lead Owner: {{summaryLead.lead_owner||'Unassigned'}} · 🆔 {{summaryLead.name}}</div><div class="form-grid"><div v-for="[label,value] in [['ID',summaryLead.name],['Name',summaryLead.lead_name],['Phone',maskPhone(summaryLead.mobile_no)],['Age / Gender',(summaryLead.age||'—')+' / '+(summaryLead.gender||'—')],['Area',summaryLead.city],['Branch',summaryLead.branch||summaryLead.lead_assign_to_branch],['Source',summaryLead.source],['Assigned To',summaryLead.lead_owner],['Status',summaryLead.custom_cc_stage],['Sub-status',summaryLead.custom_cc_sub_status],['Categories',summaryLead.custom_treatment_interests],['Calls Made',summaryLead.custom_call_count||0],['Next Follow-up',summaryLead.custom_next_followup_date],['Portal Status',summaryLead.status],['Posting Date',summaryLead.custom_posting_date],['Created On',summaryLead.creation],['Last Updated',summaryLead.modified],['Conclusion',summaryLead.custom_conclusion_remark],['Remarks',String(summaryLead.custom_remarks||'').replace(/\[CC_PROFILE_V1\][\s\S]*?\[\/CC_PROFILE_V1\]/g,'').trim()]]" :key="label"><strong>{{label}}:</strong> {{value||'—'}}</div></div><div class="btn-row"><button class="btn btn-n btn-sm" @click="dialog.close();openDetail(summaryLead)">📞 Open Follow-Up Form</button><button class="btn btn-gy btn-sm" @click="dialog.close();openLeadHistory(summaryLead)">🕘 Lead History</button><RouterLink class="btn btn-gy btn-sm" :to="{name:'convox-history',params:{leadId:summaryLead.name}}" @click="dialog.close()">🎧 ConVox details</RouterLink><RouterLink class="btn btn-gy btn-sm" :to="{name:'cc-appointments',query:{lead:summaryLead.name}}" @click="dialog.close()">📅 Appointments</RouterLink><button class="btn btn-gy btn-sm" @click="dialog.close()">Close</button></div></template></dialog>
  <dialog ref="leadHistoryDialog" class="modal-box cc-summary-modal"><h2 class="modal-title">Lead History — {{leadHistoryLead?.lead_name||leadHistoryLead?.name}}</h2><p v-if="leadHistoryBusy" role="status">Loading history…</p><p v-if="leadHistoryError" class="cc-error" role="alert">{{leadHistoryError}}</p><div v-for="(event,index) in leadHistoryRows" :key="index" class="wf-event"><b>{{event.creation||event.time||"Lead change"}} · {{event.owner||event.by||"User"}}</b><template v-for="(change,changeIndex) in leadHistoryChanges(event)" :key="changeIndex"><span><strong>{{leadHistoryLabels[change[0]]||change[0]}}:</strong> {{change[1]||"—"}} → {{change[2]||"—"}}</span></template></div><p v-if="!leadHistoryBusy&&!leadHistoryError&&!leadHistoryRows.length">No tracked changes are available for this lead.</p><div class="btn-row"><RouterLink v-if="leadHistoryLead" class="btn btn-gy btn-sm" :to="{name:'convox-history',params:{leadId:leadHistoryLead.name}}" @click="leadHistoryDialog?.close()">🎧 ConVox details</RouterLink><button class="btn btn-gy btn-sm" @click="leadHistoryDialog?.close()">Close</button></div></dialog>
  <dialog ref="createDialog" class="cc-create-dialog" aria-labelledby="create-title"><form @submit.prevent="createLead"><header><div><h2 id="create-title">Add new lead</h2><p class="cc-note">Lead is checked for a duplicate mobile number before it is created.</p></div><button type="button" aria-label="Close" @click="createDialog?.close()">×</button></header><p v-if="createMastersLoading" role="status">Loading branches, sources and categories…</p><div class="cc-create-grid"><label>Full Name *<input v-model="createForm.first_name" required></label><label>Mobile No *<input v-model="createForm.mobile_no" type="tel" inputmode="numeric" maxlength="10" required></label><label>Alternate Phone<input v-model="createForm.phone" type="tel" inputmode="numeric" maxlength="10"></label><label>Email<input v-model="createForm.email_id" type="email"></label><label>Age<input v-model="createForm.age" type="number" min="1"></label><label>Gender<select v-model="createForm.gender"><option value="">Select</option><option>Male</option><option>Female</option><option>Other</option></select></label><label>Client Area<input v-model="createForm.city"></label><label>Source *<select v-model="createForm.source" required><option value="">Select source</option><option v-for="source in addLeadSources" :key="source">{{source}}</option></select></label><label>Branch *<select v-model="createForm.branch" required><option value="">Select branch</option><option v-for="branch in createBranches" :key="branch">{{branch}}</option></select></label><label>Category<select v-model="createForm.category"><option value="">Select category</option><option v-for="category in createCategories" :key="category">{{category}}</option></select></label><label>Lead Owner <select v-if="canEditLeadOwner" v-model="createForm.lead_owner"><option value="">Auto-assign (round-robin)</option><option v-for="owner in createOwners" :key="owner.id" :value="owner.id">{{owner.name}}</option></select><input v-else :value="session.full_name||session.user" disabled></label><label>Enquired For<input v-model="createForm.enquired_for"></label><label class="cc-wide">Remarks<textarea v-model="createForm.custom_remarks" rows="3"></textarea></label></div><p class="cc-note">{{canEditLeadOwner?'Leave Lead Owner blank to auto-assign by round-robin.':'Lead owner is set to you.'}} Status starts as <b>NEW LEAD</b>.</p><div v-if="createDuplicate" class="cc-error">Possible duplicate: {{createDuplicate.lead_name||createDuplicate.name}} · {{maskPhone(createDuplicate.mobile_no)}} <button type="button" @click="openDetail(createDuplicate);createDialog?.close()">Open existing lead</button></div><p v-if="createError" class="cc-error" role="alert">{{createError}}</p><footer><button type="button" @click="createDialog?.close()">Cancel</button><button class="cc-primary" :disabled="createBusy">{{createBusy?'Creating…':'Create lead'}}</button></footer></form></dialog>
</section>
</template>
